-- C325 Microsoft Planner Masterclass: 2-day non-WSQ twin of TGS-2024042307
-- (WSQ - Fundamentals of Microsoft Project Management); courseware v1.0 replicated from the parent.
--
-- 1. Fee $350 -> $700 (2 days at $350/day), every scope row.
-- 2. Duration tile 7.5 -> 15 hrs; Sessions tile 1 -> 2.
-- 3. Course topics (`description`) copied from the WSQ parent as a literal (the parent value
--    carries NBSPs inside the LSN_DATA JSON, normalised to plain spaces); store-scope
--    overrides removed.
-- 4. "What's This Course About" follows the parent, naming this course; no day count.
-- 5. Funding block created (C325 had none) and linked to the WSQ twin.
-- meta_description already states no day count and is left alone. The schedule template
-- (A04 -> B07, the counterpart of the parent's (SG) WSQ-B07) is switched through the code path.
--
-- SG-only (store guard + TGS- parent must exist) -> no-op on MY/GH. Idempotent.
-- Post-deploy: flat reindex + flush.

SET @sg  := (SELECT COUNT(*) FROM core_store WHERE store_id = 1 AND code = 'singapore');
SET @pid := (SELECT entity_id FROM catalog_product_entity WHERE TRIM(sku) = 'C325' LIMIT 1);
SET @src := (SELECT entity_id FROM catalog_product_entity WHERE TRIM(sku) = 'TGS-2024042307' LIMIT 1);
SET @ok  := (@sg = 1 AND @pid IS NOT NULL AND @src IS NOT NULL);

SET @a_price := (SELECT attribute_id FROM eav_attribute WHERE entity_type_id = 4 AND attribute_code = 'price');
SET @a_dur   := (SELECT attribute_id FROM eav_attribute WHERE entity_type_id = 4 AND attribute_code = 'duration');
SET @a_sess  := (SELECT attribute_id FROM eav_attribute WHERE entity_type_id = 4 AND attribute_code = 'sessions');
SET @a_short := (SELECT attribute_id FROM eav_attribute WHERE entity_type_id = 4 AND attribute_code = 'short_description');
SET @a_desc  := (SELECT attribute_id FROM eav_attribute WHERE entity_type_id = 4 AND attribute_code = 'description');

UPDATE catalog_product_entity_decimal SET value = 700
 WHERE @ok AND entity_id = @pid AND attribute_id = @a_price;

UPDATE catalog_product_entity_varchar SET value = '15'
 WHERE @ok AND entity_id = @pid AND attribute_id = @a_dur;

UPDATE catalog_product_entity_varchar SET value = '2'
 WHERE @ok AND entity_id = @pid AND attribute_id = @a_sess;

INSERT INTO catalog_product_entity_text (entity_type_id, attribute_id, store_id, entity_id, value)
SELECT 4, @a_short, 0, @pid, '<p>Embark on a journey to master project management with Microsoft Project in our Microsoft Planner Masterclass. This program is specifically tailored to equip you with the skills required for the effective execution of small-scale projects. Gain a thorough understanding of how to develop and implement project plans using the robust tools offered by Microsoft Project. The course will guide you through the intricacies of tracking project progress, identifying potential risks, and employing strategies to mitigate these risks, ensuring your projects remain on track and within scope.</p>\n<p>Beyond the technical aspects, this course emphasizes the importance of collaboration and communication with stakeholders. Learn to deploy resources efficiently and manage project schedules effectively. You will acquire the skills to track deliverables against timelines, ensuring all project components are completed within the stipulated deadlines. This course is ideal for individuals looking to enhance their project management capabilities, particularly in leveraging Microsoft Project as a powerful tool for successful project completion. With hands-on experience and practical knowledge, you\'ll emerge well-prepared to tackle the challenges of project management in any professional setting.</p>'
  FROM DUAL WHERE @ok
ON DUPLICATE KEY UPDATE value = VALUES(value);

INSERT INTO catalog_product_entity_text (entity_type_id, attribute_id, store_id, entity_id, value)
SELECT 4, @a_desc, 0, @pid, '<!-- LSN_DATA: [{"title":"Topic 1 Introduction to Microsoft Project","subsecs":[{"title":"Describe how Project relates to the discipline of Project management.","links":[]},{"title":"Navigate to the primary views available using the Ribbon.","links":[]},{"title":"Choose Views that display task, resource, or assignment information.","links":[]},{"title":"Select table within views to change the information that is available to see and edit.","links":[]},{"title":"Relate the features of Project to the 5 steps for building a plan in Project.","links":[]}]},{"title":"Topic 2 A Quick and Easy Overview of Managing with Project","subsecs":[{"title":"Create a new project and prepare it for data entry.","links":[]},{"title":"Enter project tasks.","links":[]},{"title":"Sequence the tasks.","links":[]},{"title":"Define resources.","links":[]},{"title":"Estimate Task duration and assign resources.","links":[]},{"title":"Baseline the project.","links":[]},{"title":"Track project progress.","links":[]}]},{"title":"Topic 3 Setting Up a Project","subsecs":[{"title":"Use multiple methods to create a new project from an Excel file and a SharePoint Tasks list.","links":[]},{"title":"Establish one or more calendars to constrain resource availability.","links":[]},{"title":"Configure Project to calculate the schedule from the Start Date forward, or from the Finish Date","links":[]}]},{"title":"Topic 4 Manually Schedule vs. Auto Schedule","subsecs":[{"title":"Understand how to turn on Manually Schedule and Auto Schedule.","links":[]},{"title":"Understand when to use Manually Schedule.","links":[]},{"title":"Understand the limitations of Manually Scheduling.","links":[]}]},{"title":"Topic 5 Creating a Work Breakdown Structure (WBS)","subsecs":[{"title":"Build and use summary and subordinate tasks.","links":[]},{"title":"Understand and use milestones.","links":[]},{"title":"Develop WBS Outlines.","links":[]},{"title":"Assign completion criteria.","links":[]},{"title":"Evaluate the WBS.","links":[]},{"title":"Understand and use WBS templates.","links":[]}]},{"title":"Topic 6 Identifying Task Relationships","subsecs":[{"title":"Understand the different types of task relationships.","links":[]},{"title":"Understand and use various methods to create relationships.","links":[]},{"title":"Determine and display task sequence.","links":[]},{"title":"Understand and use lag, lead, and delay.","links":[]},{"title":"Understand the new feature of Task Paths.","links":[]}]},{"title":"Topic 7 Defining Resources within Project","subsecs":[{"title":"Define resource types.","links":[]},{"title":"Define individual resources that will be used on the project.","links":[]},{"title":"Record the cost (s) of using each type of resource.","links":[]},{"title":"Record the limit of availability for each type of resource by establishing a resource calendar.","links":[]}]},{"title":"Topic 8 Making Work Package Estimates","subsecs":[{"title":"Enter estimates for duration and costs for each task.","links":[]},{"title":"Distinguish between task types and describe when each is appropriate.","links":[]},{"title":"Describe the relationship between work, units, and duration.","links":[]},{"title":"Describe the way Effort Driven scheduling is affected by work, units, and duration.","links":[]},{"title":"Assign tasks to resources using the Team Planner view.","links":[]}]},{"title":"Topic 9 Creating an Initial Schedule","subsecs":[{"title":"Calculate float and identify a projects critical path.","links":[]},{"title":"Understand and identify task constraints.","links":[]},{"title":"Create milestones.","links":[]},{"title":"Use the Task Inspector to troubleshoot the initial schedule.","links":[]}]},{"title":"Topic 10 Create a Resource Leveled Schedule","subsecs":[{"title":"Adjust a project schedule to account for limited people and other resources.","links":[]},{"title":"View the overall cost and schedule of a project.","links":[]},{"title":"Identify resources that have been over allocated for a project schedule.","links":[]},{"title":"Use multiple ways to adjust tasks and assignments to remove over allocation for any resource.","links":[]}]},{"title":"Topic 11 Managing the Project","subsecs":[{"title":"Learn how to set a baseline.","links":[]},{"title":"Lean how to enter and track project performance data.","links":[]},{"title":"Learn how to apply different tracking methods.","links":[]},{"title":"Learn how to perform a variance analysis on a project.","links":[]}]}] -->\n<p><strong>Topic 1 Introduction to Microsoft Project </strong></p>\n<p><em>Describe how Project relates to the discipline of Project management.</em></p>\n<p><em>Navigate to the primary views available using the Ribbon.</em></p>\n<p><em>Choose Views that display task, resource, or assignment information.</em></p>\n<p><em>Select table within views to change the information that is available to see and edit.</em></p>\n<p><em>Relate the features of Project to the 5 steps for building a plan in Project.</em></p>\n<p><strong>Topic 2 A Quick and Easy Overview of Managing with Project </strong></p>\n<p><em>Create a new project and prepare it for data entry.</em></p>\n<p><em>Enter project tasks.</em></p>\n<p><em>Sequence the tasks.</em></p>\n<p><em>Define resources.</em></p>\n<p><em>Estimate Task duration and assign resources.</em></p>\n<p><em>Baseline the project.</em></p>\n<p><em>Track project progress.</em></p>\n<p><strong>Topic 3 Setting Up a Project</strong></p>\n<p><em>Use multiple methods to create a new project from an Excel file and a SharePoint Tasks list.</em></p>\n<p><em>Establish one or more calendars to constrain resource availability.</em></p>\n<p><em>Configure Project to calculate the schedule from the Start Date forward, or from the Finish Date</em></p>\n<p><strong>Topic 4 Manually Schedule vs. Auto Schedule</strong></p>\n<p><em>Understand how to turn on Manually Schedule and Auto Schedule.</em></p>\n<p><em>Understand when to use Manually Schedule.</em></p>\n<p><em>Understand the limitations of Manually Scheduling.</em></p>\n<p><strong>Topic 5 Creating a Work Breakdown Structure (WBS)</strong></p>\n<p><em>Build and use summary and subordinate tasks.</em></p>\n<p><em>Understand and use milestones.</em></p>\n<p><em>Develop WBS Outlines.</em></p>\n<p><em>Assign completion criteria.</em></p>\n<p><em>Evaluate the WBS.</em></p>\n<p><em>Understand and use WBS templates.</em></p>\n<p><strong>Topic 6 Identifying Task Relationships</strong></p>\n<p><em>Understand the different types of task relationships.</em></p>\n<p><em>Understand and use various methods to create relationships.</em></p>\n<p><em>Determine and display task sequence.</em></p>\n<p><em>Understand and use lag, lead, and delay.</em></p>\n<p><em>Understand the new feature of Task Paths.</em></p>\n<p><strong>Topic 7 Defining Resources within Project </strong></p>\n<p><em>Define resource types.</em></p>\n<p><em>Define individual resources that will be used on the project.</em></p>\n<p><em>Record the cost (s) of using each type of resource.</em></p>\n<p><em>Record the limit of availability for each type of resource by establishing a resource calendar.</em></p>\n<p><strong>Topic 8 Making Work Package Estimates </strong></p>\n<p><em>Enter estimates for duration and costs for each task.</em></p>\n<p><em>Distinguish between task types and describe when each is appropriate.</em></p>\n<p><em>Describe the relationship between work, units, and duration.</em></p>\n<p><em>Describe the way Effort Driven scheduling is affected by work, units, and duration.</em></p>\n<p><em>Assign tasks to resources using the Team Planner view.</em></p>\n<p><strong>Topic 9 Creating an Initial Schedule</strong></p>\n<p><em>Calculate float and identify a projects critical path.</em></p>\n<p><em>Understand and identify task constraints.</em></p>\n<p><em>Create milestones.</em></p>\n<p><em>Use the Task Inspector to troubleshoot the initial schedule.</em></p>\n<p><strong>Topic 10 Create a Resource Leveled Schedule </strong></p>\n<p><em>Adjust a project schedule to account for limited people and other resources.</em></p>\n<p><em>View the overall cost and schedule of a project.</em></p>\n<p><em>Identify resources that have been over allocated for a project schedule.</em></p>\n<p><em>Use multiple ways to adjust tasks and assignments to remove over allocation for any resource.</em></p>\n<p><strong>Topic 11 Managing the Project </strong></p>\n<p><em>Learn how to set a baseline.</em></p>\n<p><em>Lean how to enter and track project performance data.</em></p>\n<p><em>Learn how to apply different tracking methods.</em></p>\n<p><em>Learn how to perform a variance analysis on a project.</em></p>\n'
  FROM DUAL WHERE @ok
ON DUPLICATE KEY UPDATE value = VALUES(value);

DELETE FROM catalog_product_entity_text
 WHERE @ok AND entity_id = @pid AND attribute_id IN (@a_short, @a_desc) AND store_id <> 0;

-- ------------------------------------------------------ funding block -----
INSERT INTO cms_block (title, identifier, content, creation_time, update_time, is_active)
SELECT 'Course C325 - Funding and Grant', 'course_C325_funding_and_grant', '', NOW(), NOW(), 1
  FROM DUAL
 WHERE @ok AND NOT EXISTS (SELECT 1 FROM cms_block WHERE identifier = 'course_C325_funding_and_grant');

INSERT IGNORE INTO cms_block_store (block_id, store_id)
SELECT block_id, 0 FROM cms_block
 WHERE @ok AND identifier = 'course_C325_funding_and_grant'
   AND NOT EXISTS (SELECT 1 FROM cms_block_store s JOIN cms_block b ON b.block_id = s.block_id
                    WHERE b.identifier = 'course_C325_funding_and_grant');

UPDATE cms_block
   SET content = '<h2>Funding and Grant Applications</h2>\r\n<p>No funding is available for this course</p>\r\n<p>For WSQ funding, please checkout the details at&nbsp;<span style="text-decoration: underline;"><a href="https://www.tertiarycourses.com.sg/wsq-fundamentals-of-microsoft-project-management.html" title="WSQ - Fundamentals of Microsoft Project Management">WSQ - Fundamentals of Microsoft Project Management</a></span></p>',
       update_time = NOW()
 WHERE @ok AND identifier = 'course_C325_funding_and_grant';
